{"path": "/tmp/sv-0e46d11094004ff2866f4f453e3f52d5/Components/Pages/Apply/WorkHistoryStep.razor", "file_text": "@namespace sv_0e46d11094004ff2866f4f453e3f52d5.Components.Pages.Apply

<div class="step-content">
    <h2>Work History</h2>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        var entry = Entries[index];
        <WorkEntryForm Index="index"
                       Company="@entry.Company"
                       Title="@entry.Title"
                       StartDate="@entry.StartDate"
                       EndDate="@entry.EndDate"
                       IsCurrent="@entry.IsCurrent"
                       Description="@entry.Description"
                       CanRemove="@(Entries.Count > 1)"
                       CompanyChanged="e => UpdateEntry(index, entry with { Company = e })"
                       TitleChanged="e => UpdateEntry(index, entry with { Title = e })"
                       StartDateChanged="e => UpdateEntry(index, entry with { StartDate = e })"
                       EndDateChanged="e => UpdateEntry(index, entry with { EndDate = e })"
                       IsCurrentChanged="e => UpdateEntry(index, entry with { IsCurrent = e, EndDate = e ? null : entry.EndDate })"
                       DescriptionChanged="e => UpdateEntry(index, entry with { Description = e })"
                       OnRemove="() => RemoveEntry(index)" />
    }

    <button class="btn btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    @if (!string.IsNullOrEmpty(ValidationError))
    {
        <div class="validation-summary">@ValidationError</div>
    }

    <div class="step-actions">
        <button class="btn btn-outline" @onclick="OnBack">Back</button>
        <button class="btn btn-primary" @onclick="OnNext">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<WorkEntryModel> Entries { get; set; } = new();
    [Parameter] public string? ValidationError { get; set; }
    [Parameter] public EventCallback<List<WorkEntryModel>> EntriesChanged { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }

    private void UpdateEntry(int index, WorkEntryModel updated)
    {
        var list = new List<WorkEntryModel>(Entries);
        list[index] = updated;
        EntriesChanged.InvokeAsync(list);
    }

    private void AddEntry()
    {
        var list = new List<WorkEntryModel>(Entries) { new() };
        EntriesChanged.InvokeAsync(list);
    }

    private void RemoveEntry(int index)
    {
        var list = new List<WorkEntryModel>(Entries);
        list.RemoveAt(index);
        EntriesChanged.InvokeAsync(list);
    }

    public record WorkEntryModel
    {
        public string Company { get; init; } = "";
        public string Title { get; init; } = "";
        public DateTime StartDate { get; init; } = DateTime.Today;
        public DateTime? EndDate { get; init; }
        public bool IsCurrent { get; init; }
        public string Description { get; init; } = "";
    }
}
"}

