<div class="step-content">
    <h2>References</h2>
    <p class="step-description">Please provide 2–3 professional references.</p>

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        var r = References[index];
        <ReferenceForm Index="index"
                       Name="@r.Name"
                       Relationship="@r.Relationship"
                       Email="@r.Email"
                       Phone="@r.Phone"
                       CanRemove="@(References.Count > 2)"
                       NameChanged="e => UpdateRef(index, r with { Name = e })"
                       RelationshipChanged="e => UpdateRef(index, r with { Relationship = e })"
                       EmailChanged="e => UpdateRef(index, r with { Email = e })"
                       PhoneChanged="e => UpdateRef(index, r with { Phone = e })"
                       OnRemove="() => RemoveRef(index)" />
    }

    @if (References.Count < 3)
    {
        <button class="btn btn-secondary" @onclick="AddRef">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(ValidationError))
    {
        <div class="validation-summary">@ValidationError</div>
    }

    <div class="step-actions">
        <button class="btn btn-outline" @onclick="OnBack">Back</button>
        <button class="btn btn-primary" @onclick="OnNext">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = new();
    [Parameter] public string? ValidationError { get; set; }
    [Parameter] public EventCallback<List<ReferenceModel>> ReferencesChanged { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }

    private void UpdateRef(int index, ReferenceModel updated)
    {
        var list = new List<ReferenceModel>(References);
        list[index] = updated;
        ReferencesChanged.InvokeAsync(list);
    }

    private void AddRef()
    {
        if (References.Count < 3)
        {
            var list = new List<ReferenceModel>(References) { new() };
            ReferencesChanged.InvokeAsync(list);
        }
    }

    private void RemoveRef(int index)
    {
        var list = new List<ReferenceModel>(References);
        list.RemoveAt(index);
        ReferencesChanged.InvokeAsync(list);
    }

    public record ReferenceModel
    {
        public string Name { get; init; } = "";
        public string Relationship { get; init; } = "";
        public string Email { get; init; } = "";
        public string Phone { get; init; } = "";
    }
}
"}

