@page "/apply"
@rendermode InteractiveServer
@using sv_0e46d11094004ff2866f4f453e3f52d5.Models
@namespace sv_0e46d11094004ff2866f4f453e3f52d5.Components.Pages.Apply
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-page">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="currentStep" StepNames="stepNames" OnStepClicked="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep FullName="@fullName" Email="@email" Phone="@phone" Address="@address"
                              EmailError="@emailError" ValidationError="@validationError" IsValidating="@isValidating"
                              FullNameChanged="v => { fullName = v; ClearErrors(); }"
                              EmailChanged="v => { email = v; emailError = null; ClearErrors(); }"
                              PhoneChanged="v => { phone = v; ClearErrors(); }"
                              AddressChanged="v => { address = v; ClearErrors(); }"
                              OnNext="ValidateAndAdvancePersonalInfo" />
            break;
        case 1:
            <WorkHistoryStep Entries="workEntries" ValidationError="@validationError"
                             EntriesChanged="v => { workEntries = v; ClearErrors(); }"
                             OnBack="() => GoToStep(0)"
                             OnNext="ValidateAndAdvanceWorkHistory" />
            break;
        case 2:
            <ReferencesStep References="references" ValidationError="@validationError"
                            ReferencesChanged="v => { references = v; ClearErrors(); }"
                            OnBack="() => GoToStep(1)"
                            OnNext="ValidateAndAdvanceReferences" />
            break;
        case 3:
            <CoverLetterStep CoverLetter="@coverLetter"
                             CoverLetterChanged="v => coverLetter = v"
                             OnBack="() => GoToStep(2)"
                             OnNext="() => GoToStep(4)" />
            break;
        case 4:
            <ReviewStep FullName="@fullName" Email="@email" Phone="@phone" Address="@address"
                        WorkEntries="workEntries" References="references" CoverLetter="@coverLetter"
                        IsSubmitting="@isSubmitting" IsSubmitted="@isSubmitted"
                        ApplicationId="@applicationId" SubmitError="@submitError"
                        OnEditStep="GoToStep"
                        OnBack="() => GoToStep(3)"
                        OnSubmit="SubmitApplication" />
            break;
    }
</div>

@code {
    private int currentStep = 0;
    private readonly List<string> stepNames = new()
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    // Step 1
    private string fullName = "";
    private string email = "";
    private string phone = "";
    private string address = "";
    private string? emailError;
    private bool isValidating;

    // Step 2
    private List<WorkHistoryStep.WorkEntryModel> workEntries = new() { new() };

    // Step 3
    private List<ReferencesStep.ReferenceModel> references = new() { new(), new() };

    // Step 4
    private string coverLetter = "";

    // Step 5
    private bool isSubmitting;
    private bool isSubmitted;
    private int applicationId;
    private string? submitError;

    // Shared
    private string? validationError;

    private void ClearErrors()
    {
        validationError = null;
    }

    private void GoToStep(int step)
    {
        if (step <= currentStep)
        {
            currentStep = step;
            ClearErrors();
        }
    }

    private async Task ValidateAndAdvancePersonalInfo()
    {
        if (string.IsNullOrWhiteSpace(fullName) || string.IsNullOrWhiteSpace(email)
            || string.IsNullOrWhiteSpace(phone) || string.IsNullOrWhiteSpace(address))
        {
            validationError = "All fields are required.";
            return;
        }

        isValidating = true;
        try
        {
            var isEmailValid = await ApplicationService.ValidateEmailAsync(email);
            if (!isEmailValid)
            {
                emailError = "This email address is not valid.";
                return;
            }
        }
        finally
        {
            isValidating = false;
        }

        emailError = null;
        currentStep = 1;
    }

    private void ValidateAndAdvanceWorkHistory()
    {
        foreach (var entry in workEntries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                validationError = "Each position must have a company name and job title.";
                return;
            }
        }
        currentStep = 2;
    }

    private void ValidateAndAdvanceReferences()
    {
        foreach (var r in references)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
                || string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                validationError = "All reference fields are required.";
                return;
            }
        }
        currentStep = 3;
    }

    private async Task SubmitApplication()
    {
        isSubmitting = true;
        submitError = null;

        try
        {
            var personal = new PersonalInfo(fullName, email, phone, address);
            var work = new WorkHistory(workEntries.Select(e => new WorkEntry(
                e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description
            )).ToList());
            var refs = references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
            var application = new JobApplication(personal, work, refs, coverLetter);

            applicationId = await ApplicationService.SubmitApplicationAsync(application);
            isSubmitted = true;
        }
        catch (Exception ex)
        {
            submitError = $"Submission failed: {ex.Message}";
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

