arguments.file_text:
.apply-page {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem 1rem;
}

.apply-page h1 {
    text-align: center;
    margin-bottom: 2rem;
}

/* Step Indicator */
.step-indicator {
    margin-bottom: 2rem;
}

.step-list {
    display: flex;
    align-items: center;
    justify-content: center;
    list-style: none;
    padding: 0;
    margin: 0;
    gap: 0;
}

.step-item {
    display: flex;
    align-items: center;
}

.step-button {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.25rem;
    padding: 0.5rem;
    border: none;
    background: none;
    cursor: default;
    text-decoration: none;
    font-size: 0.85rem;
}

button.step-button.completed {
    cursor: pointer;
}

button.step-button.completed:hover .step-label {
    text-decoration: underline;
}

.step-icon {
    width: 2rem;
    height: 2rem;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    border: 2px solid #ccc;
    color: #999;
    background: #f9f9f9;
}

.step-item.active .step-icon {
    border-color: #0d6efd;
    background: #0d6efd;
    color: white;
}

.step-item.completed .step-icon {
    border-color: #198754;
    background: #198754;
    color: white;
}

.step-item.future .step-label {
    color: #999;
}

.step-item.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step-item.completed .step-label {
    color: #198754;
}

.step-connector {
    width: 2rem;
    height: 2px;
    background: #ccc;
    list-style: none;
}

.step-connector.completed {
    background: #198754;
}

/* Step Content */
.step-content {
    background: #fff;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 2rem;
}

.step-content h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
}

.step-description {
    color: #666;
    margin-bottom: 1rem;
}

/* Forms */
.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.25rem;
    font-weight: 500;
    font-size: 0.9rem;
}

.form-control {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 1rem;
    box-sizing: border-box;
}

.form-control:focus {
    outline: none;
    border-color: #0d6efd;
    box-shadow: 0 0 0 2px rgba(13, 110, 253, 0.15);
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.checkbox-label {
    display: inline-flex !important;
    align-items: center;
    gap: 0.5rem;
    font-weight: normal !important;
    margin-top: 0.5rem;
}

.checkbox-label input[type="checkbox"] {
    width: auto;
}

/* Buttons */
.step-actions {
    display: flex;
    justify-content: space-between;
    margin-top: 2rem;
    padding-top: 1rem;
    border-top: 1px solid #eee;
}

.btn {
    padding: 0.6rem 1.5rem;
    border: none;
    border-radius: 4px;
    font-size: 1rem;
    cursor: pointer;
    font-weight: 500;
}

.btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-primary {
    background: #0d6efd;
    color: white;
    margin-left: auto;
}

.btn-primary:hover:not(:disabled) {
    background: #0b5ed7;
}

.btn-outline {
    background: transparent;
    border: 1px solid #ccc;
    color: #333;
}

.btn-outline:hover {
    background: #f5f5f5;
}

.btn-secondary {
    background: #f0f0f0;
    color: #333;
    border: 1px dashed #aaa;
    margin-bottom: 1rem;
}

.btn-secondary:hover {
    background: #e0e0e0;
}

.btn-danger {
    background: #dc3545;
    color: white;
}

.btn-sm {
    padding: 0.25rem 0.75rem;
    font-size: 0.85rem;
}

.btn-link {
    background: none;
    border: none;
    color: #0d6efd;
    cursor: pointer;
    font-size: 0.9rem;
    padding: 0;
}

.btn-link:hover {
    text-decoration: underline;
}

.btn-submit {
    padding: 0.75rem 2rem;
    font-size: 1.1rem;
}

/* Work Entry / Reference Cards */
.work-entry-card,
.reference-card {
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    padding: 1.5rem;
    margin-bottom: 1rem;
    background: #fafafa;
}

.work-entry-header,
.reference-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.work-entry-header h4,
.reference-header h4 {
    margin: 0;
    font-size: 1.1rem;
}

/* Errors */
.field-error {
    color: #dc3545;
    font-size: 0.85rem;
    margin-top: 0.25rem;
    display: block;
}

.validation-summary {
    background: #fff3cd;
    border: 1px solid #ffc107;
    color: #856404;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    margin-top: 1rem;
}

/* Cover Letter */
.cover-letter-textarea {
    min-height: 250px;
    resize: vertical;
}

.character-count {
    display: block;
    text-align: right;
    font-size: 0.85rem;
    color: #666;
    margin-top: 0.25rem;
}

.character-count.at-limit {
    color: #dc3545;
    font-weight: 600;
}

/* Review Step */
.review-section {
    border-bottom: 1px solid #eee;
    padding-bottom: 1.5rem;
    margin-bottom: 1.5rem;
}

.review-section:last-of-type {
    border-bottom: none;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.review-header h3 {
    margin: 0;
    font-size: 1.2rem;
}

.review-data {
    display: grid;
    grid-template-columns: 120px 1fr;
    gap: 0.5rem;
    margin: 0;
}

.review-data dt {
    font-weight: 600;
    color: #555;
}

.review-data dd {
    margin: 0;
}

.review-work-entry,
.review-reference {
    margin-bottom: 0.75rem;
    padding: 0.5rem 0;
}

.review-description {
    margin: 0.5rem 0 0;
    color: #555;
    font-size: 0.9rem;
}

.review-cover-letter {
    white-space: pre-wrap;
    background: #f9f9f9;
    padding: 1rem;
    border-radius: 4px;
    font-size: 0.95rem;
}

.text-muted {
    color: #666;
    font-size: 0.9rem;
}

/* Submission Confirmation */
.submission-confirmation {
    text-align: center;
    padding: 3rem 1rem;
}

.success-icon {
    width: 4rem;
    height: 4rem;
    border-radius: 50%;
    background: #198754;
    color: white;
    font-size: 2rem;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto 1.5rem;
}

.submission-confirmation h3 {
    color: #198754;
    margin-bottom: 1rem;
}

.apply-page {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem 1rem;
}

.apply-page h1 {
    text-align: center;
    margin-bottom: 2rem;
}

/* Step Indicator */
.step-indicator {
    margin-bottom: 2rem;
}

.step-list {
    display: flex;
    align-items: center;
    justify-content: center;
    list-style: none;
    padding: 0;
    margin: 0;
    gap: 0;
}

.step-item {
    display: flex;
    align-items: center;
}

